mapper.select:
SELECT club.id as clubId, club.region as region, club.university as university, club.club_name as clubName, club.sport_category as sportCategory, club.manner_score as mannerScore
FROM club WHERE 1=1 AND club.deleted = false AND club.id != #{requestClubId}
AND club.sport_category IN
#{sportCategory}
AND club.region IN
#{region}
AND (club.club_name LIKE CONCAT('%', #{listReqDto.keyword}, '%') OR club.university LIKE CONCAT('%', #{listReqDto.keyword}, '%'))
ORDER BY club.created_at DESC
